impl RBFT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<RBF<'b>> {
        let RBF_ID = Some({
            let x = &self.RBF_ID;
            _fbb.create_string(x)
        });
        let BODY_NAME = Some({
            let x = &self.BODY_NAME;
            _fbb.create_string(x)
        });
        let BODY_NAIF_ID = self.BODY_NAIF_ID;
        let MODEL = self.MODEL;
        let MODEL_VERSION = self.MODEL_VERSION.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let MAG_MODEL_ID = self.MAG_MODEL_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let REFERENCE_FRAME = self.REFERENCE_FRAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SPECIES = self.SPECIES;
        let FLUX_TYPE = self.FLUX_TYPE;
        let UNITS = Some({
            let x = &self.UNITS;
            _fbb.create_string(x)
        });
        let EPOCH = Some({
            let x = &self.EPOCH;
            _fbb.create_string(x)
        });
        let KP = self.KP;
        let HAS_KP = self.HAS_KP;
        let DST_NT = self.DST_NT;
        let HAS_DST_NT = self.HAS_DST_NT;
        let F107 = self.F107;
        let HAS_F107 = self.HAS_F107;
        let SOLAR_WIND_PRESSURE_NPA = self.SOLAR_WIND_PRESSURE_NPA;
        let HAS_SOLAR_WIND_PRESSURE = self.HAS_SOLAR_WIND_PRESSURE;
        let QUANTILE_PCT = self.QUANTILE_PCT;
        let L_SHELLS = self.L_SHELLS.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let ENERGY_MEV = self.ENERGY_MEV.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let B_OVER_B0 = self.B_OVER_B0.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let FLUX_GRID = self.FLUX_GRID.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let STRUCTURES = self.STRUCTURES.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let SAA_CONTOURS = self.SAA_CONTOURS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let SPACE_WEATHER_REFS = self.SPACE_WEATHER_REFS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let PROVENANCE = Some({
            let x = &self.PROVENANCE;
            x.pack(_fbb)
        });
        RBF::create(_fbb, &RBFArgs{
            RBF_ID,
            BODY_NAME,
            BODY_NAIF_ID,
            MODEL,
            MODEL_VERSION,
            MAG_MODEL_ID,
            REFERENCE_FRAME,
            SPECIES,
            FLUX_TYPE,
            UNITS,
            EPOCH,
            KP,
            HAS_KP,
            DST_NT,
            HAS_DST_NT,
            F107,
            HAS_F107,
            SOLAR_WIND_PRESSURE_NPA,
            HAS_SOLAR_WIND_PRESSURE,
            QUANTILE_PCT,
            L_SHELLS,
            ENERGY_MEV,
            B_OVER_B0,
            FLUX_GRID,
            STRUCTURES,
            SAA_CONTOURS,
            SPACE_WEATHER_REFS,
            PROVENANCE,
        })
    }
}

/// Verifies that a buffer of bytes contains a `RBF`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_rbf_unchecked`.
#[inline]
pub fn root_as_rbf(buf: &[u8]) -> Result<RBF<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<RBF>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `RBF` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_rbf_unchecked`.
#[inline]
pub fn size_prefixed_root_as_rbf(buf: &[u8]) -> Result<RBF<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<RBF>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `RBF` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_rbf_unchecked`.
#[inline]
pub fn root_as_rbf_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<RBF<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<RBF<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `RBF` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_rbf_unchecked`.
#[inline]
pub fn size_prefixed_root_as_rbf_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<RBF<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<RBF<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a RBF and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `RBF`.
#[inline]
pub unsafe fn root_as_rbf_unchecked(buf: &[u8]) -> RBF<'_> {
    unsafe { ::flatbuffers::root_unchecked::<RBF>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed RBF and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `RBF`.
#[inline]
pub unsafe fn size_prefixed_root_as_rbf_unchecked(buf: &[u8]) -> RBF<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<RBF>(buf) }
}

pub const RBF_IDENTIFIER: &str = "$RBF";

#[inline]
pub fn rbf_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, RBF_IDENTIFIER, false)
}

#[inline]
pub fn rbf_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, RBF_IDENTIFIER, true)
}

#[inline]
pub fn finish_rbf_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<RBF<'a>>
) {
    fbb.finish(root, Some(RBF_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_rbf_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<RBF<'a>>
) {
    fbb.finish_size_prefixed(root, Some(RBF_IDENTIFIER));
}
